import sys
from collections import deque

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    MOD = 10**9 + 7
    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            m = int(next(iterator))
            s = int(next(iterator))
            target_t = int(next(iterator))
        except StopIteration:
            break

        adj = [[] for _ in range(n + 1)]
        for _ in range(m):
            u = int(next(iterator))
            v = int(next(iterator))
            adj[u].append(v)
            adj[v].append(u)

        dist = [-1] * (n + 1)
        count = [0] * (n + 1)

        q = deque()
        dist[s] = 0
        count[s] = 1
        q.append(s)

        while q:
            u = q.popleft()

            if dist[u] > 2:
                continue

            for v in adj[u]:
                new_dist = dist[u] + 1

                if dist[v] == -1:
                    dist[v] = new_dist
                    count[v] = count[u]
                    if new_dist <= 2:
                        q.append(v)
                elif dist[v] == new_dist:
                    count[v] = (count[v] + count[u]) % MOD

        ans = 0
        min_dist = dist[target_t]

        if min_dist != -1:
            if min_dist <= 2:
                ans = count[target_t]
            else:
                ans = 0
        else:
            ans = 0

        results.append(str(ans % MOD))

    sys.stdout.write('\n'.join(results) + '\n')

if __name__ == "__main__":
    solve()
